const runId = $('Input').first().json.run_id;
const expectedCount = parseInt($('Input').first().json.expected_count, 10) || 0;
const pollCount = ($runIndex || 0) + 1;
const rows = $input.all().map(i => i.json);
const matching = rows.filter(r => String(r.run_id) === String(runId));
const count = matching.length;
const complete = count >= expectedCount;
const timeout = pollCount >= 20;
return [{ json: {
  run_id: runId,
  expected_count: expectedCount,
  count: count,
  poll_count: pollCount,
  complete: complete,
  timeout: timeout,
  results: matching,
  slack_channel: $('Input').first().json.slack_channel,
  slack_thread_ts: $('Input').first().json.slack_thread_ts,
} }];

const data = $input.first().json;
const results = Array.isArray(data.results) ? data.results : [];
const runId = data.run_id;
const timedOut = data.timeout && !data.complete;

const getScore = (r) => {
  const v = r.score ?? r.overall_score ?? r.overall ?? null;
  return (v === null || v === undefined || v === '') ? null : Number(v);
};
const getVerdict = (r) => String(r.verdict ?? r.status ?? r.result ?? '').toLowerCase();

let pass = 0, borderline = 0, fail = 0;
const failures = [];
for (const r of results) {
  const v = getVerdict(r);
  const s = getScore(r);
  let bucket = v;
  if (!bucket) {
    if (s === null) bucket = 'unknown';
    else if (s >= 0.8) bucket = 'pass';
    else if (s >= 0.5) bucket = 'borderline';
    else bucket = 'fail';
  }
  if (bucket === 'pass') pass++;
  else if (bucket === 'borderline') borderline++;
  else if (bucket === 'fail') { fail++; failures.push(r); }
}

const dimSums = {};
const dimCounts = {};
const skip = new Set(['id','run_id','created_at','createdAt','updated_at','updatedAt','verdict','status','result','case_id','case','name','notes']);
for (const r of results) {
  for (const key of Object.keys(r)) {
    if (skip.has(key)) continue;
    const num = Number(r[key]);
    if (!isNaN(num) && r[key] !== null && r[key] !== '' && typeof r[key] !== 'boolean') {
      dimSums[key] = (dimSums[key] || 0) + num;
      dimCounts[key] = (dimCounts[key] || 0) + 1;
    }
  }
}
const dimLines = Object.keys(dimSums).map(k => {
  const avg = dimSums[k] / dimCounts[k];
  return '\u2022 *' + k + '*: ' + avg.toFixed(2);
});

const failLines = failures.map(r => {
  const label = r.case_id ?? r.case ?? r.name ?? r.id ?? 'unknown';
  const s = getScore(r);
  return '\u2022 ' + label + (s !== null ? ' (score ' + s.toFixed(2) + ')' : '');
});

const lines = [];
lines.push('*Eval Results \u2014 run `' + runId + '`*');
if (timedOut) lines.push('_:warning: Timed out waiting for all results (' + data.count + '/' + data.expected_count + ' received)_');
lines.push('');
lines.push('*Summary*');
lines.push('\u2022 :white_check_mark: Pass: ' + pass);
lines.push('\u2022 :large_yellow_circle: Borderline: ' + borderline);
lines.push('\u2022 :x: Fail: ' + fail);
lines.push('\u2022 Total: ' + results.length);
if (dimLines.length) { lines.push(''); lines.push('*Average scores by dimension*'); for (const l of dimLines) lines.push(l); }
if (failLines.length) { lines.push(''); lines.push('*Failures*'); for (const l of failLines) lines.push(l); }

return [{ json: {
  summary: lines.join('\n'),
  slack_channel: data.slack_channel,
  slack_thread_ts: data.slack_thread_ts,
  pass: pass, borderline: borderline, fail: fail, total: results.length,
} }];
